#!/usr/bin/env bash
# recipes/crate-windows-x86-64-msvc--0-48-5/build.sh -- stage the windows_x86_64_msvc 0.48.5 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/windows_x86_64_msvc-0.48.5"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
