# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"ed94fce61571a4006852b7389a063ab983c02eb1bb37b47f8272ce92d06d9538"}\n' > "${dest}/.cargo-checksum.json"
